import { test, expect } from '@playwright/test';

test.describe('External Links Open in New Tab', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/external-links');
  });

  test('should open external links in a new tab with correct target attribute', async ({ page }) => {
    // Verify external link is visible
    const externalLink = page.getByRole('link', { name: /external site/i });
    await expect(externalLink).toBeVisible();

    // Verify link has correct href and target attributes
    const href = await externalLink.evaluate((el) => el.href);
    const target = await externalLink.evaluate((el) => el.getAttribute('target'));
    expect(href).toContain('https://external.com');
    expect(target).toBe('_blank');

    // Verify link opens in a new tab
    const newTabCount = await page.evaluate(() => window.open.length);
    expect(newTabCount).toBe(1);

    // Verify original page remains open
    const originalPageTitle = await page.title();
    await expect(originalPageTitle).toContain('External Links');

    // Verify new tab has correct title
    const newTab = await page.waitForURL(href);
    const newTabTitle = await newTab.title();
    expect(newTabTitle).toContain('External Site');

    // Verify navigation back to original page
    await page.goBack();
    await expect(originalPageTitle).toContain('External Links');
  });

  test('should handle multiple external links and open all in new tabs', async ({ page }) => {
    // Verify multiple external links are present
    const externalLink1 = page.getByRole('link', { name: /external site 1/i });
    const externalLink2 = page.getByRole('link', { name: /external site 2/i });
    await expect(externalLink1).toBeVisible();
    await expect(externalLink2).toBeVisible();

    // Verify both links have correct href and target attributes
    const href1 = await externalLink1.evaluate((el) => el.href);
    const href2 = await externalLink2.evaluate((el) => el.href);
    const target1 = await externalLink1.evaluate((el) => el.getAttribute('target'));
    const target2 = await externalLink2.evaluate((el) => el.getAttribute('target'));
    expect(href1).toContain('https://external1.com');
    expect(href2).toContain('https://external2.com');
    expect(target1).toBe('_blank');
    expect(target2).toBe('_blank');

    // Verify both links open in new tabs
    const newTabCount = await page.evaluate(() => window.open.length);
    expect(newTabCount).toBe(2);

    // Verify original page remains open
    const originalPageTitle = await page.title();
    await expect(originalPageTitle).toContain('External Links');

    // Verify navigation back to original page
    await page.goBack();
    await expect(originalPageTitle).toContain('External Links');
  });
});
